import numpy as np

def engine(grid, action, data):
    """
    World model for ARC-AGI game 'ls20'.
    The grid contains a "block" (a 5x5 area of colors [12, 12, 9, 9, 9]) and a "cursor"
    that moves right across rows 61 and 62, leaving a trail of color 3.
    Actions move the block in different directions or do nothing to it.
    """
    new_grid = grid.copy()
    h, w = new_grid.shape

    # Identify current cursor position based on the trail of color 3 in row 61/62.
    # The cursor is at the rightmost cell that has been changed to color 3 in those rows.
    # Based on observed transitions, the cursor starts moving from c=13 onwards.
    cc = -1
    for col in range(w - 1, 12, -1):
        if new_grid[61, col] == 3:
            cc = col
            break

    # If no trail yet, start before the first observed transition's result.
    if cc == -1:
        cc = 12

    # Every action moves the cursor one step to the right.
    cc += 1
    if cc < w:
        new_grid[61, cc] = 3
        new_grid[62, cc] = 3

    # Identify the "block" (5x5 area). It consists of colors [12, 12, 9, 9, 9].
    # We find its top-left corner (br, bc) by searching for this pattern.
    br, bc = -1, -1
    found = False
    for r in range(h - 4):
        for c in range(w - 4):
            match = True
            pattern = [12, 12, 9, 9, 9]
            for dr in range(5):
                for dc in range(5):
                    if grid[r + dr, c + dc] != pattern[dr]:
                        match = False
                        break
                if not match: break
            if match:
                br, bc = r, c
                found = True
                break
        if found: break

    # If block is not found, we can't move it. But based on data, it should be there.
    if not found:
        return new_grid

    # Block internal color pattern
    original_block_color = [12, 12, 9, 9, 9]

    if action == 1: # Move UP by 5 units
        new_br = br - 5
        if new_br >= 0:
            # Clear old position (replace with background color 3)
            for dr in range(5):
                for dc in range(5):
                    if br + dr < h and bc + dc < w:
                        new_grid[br + dr, bc + dc] = 3
            # Set new position
            for dr in range(5):
                for dc in range(5):
                    if new_br + dr < h and bc + dc < w:
                        new_grid[new_br + dr, bc + dc] = original_block_color[dr]
            br = new_br

    elif action == 3: # Move LEFT by 5 units
        new_bc = bc - 5
        if new_bc >= 0:
            # Clear old position
            for dr in range(5):
                for dc in range(5):
                    if br + dr < h and bc + dc < w:
                        new_grid[br + dr, bc + dc] = 3
            # Set new position
            for dr in range(5):
                for dc in range(5):
                    if br + dr < h and new_bc + dc < w:
                        new_grid[br + dr, new_bc + dc] = original_block_color[dr]
            bc = new_bc

    elif action == 4: # Move RIGHT by 5 units
        new_bc = bc + 5
        if new_bc <= w - 5:
            # Clear old position
            for dr in range(5):
                for dc in range(5):
                    if br + dr < h and bc + dc < w:
                        new_grid[br + dr, bc + dc] = 3
            # Set new position
            for dr in range(5):
                for dc in range(5):
                    if br + dr < h and new_bc + dc < w:
                        new_grid[br + dr, new_bc + dc] = original_block_color[dr]
            bc = new_bc

    return new_grid

def is_level_complete(grid):
    """
    The level seems to be complete when the cursor reaches a certain point.
    Based on object structure, obj16 (the path) ends at column 54.
    """
    # Check if the trail of color 3 has reached column 54 in rows 61/62.
    if grid.shape[1] > 54:
        return grid[61, 54] == 3 and grid[62, 54] == 3
    return False
